-- Sources.lua
-- Where a recipe is learned: trainer, vendor, drop, quest. The data (Data/RecipeSources.lua,
-- generated by Tools/build_sources.py from ForeverDB.net's addon data) stays packed in strings
-- and is only unpacked for the recipes somebody actually looks at. Vendors, drop sources and
-- quests are stored by ID; their names come from Data/Names/<locale>.lua.
local _, ns = ...
local L = ns.L

local COLOR_LABEL = "ffffd100"
local COLOR_NOTE = "ff888888"
local MERCHANTS_FAVOR = 3402 -- currency ID (CurrencyTypes)

-- Filter values of the recipe window, in display order
ns.SOURCE_KINDS = { "TRAINER", "VENDOR", "DROP", "QUEST", "OTHER" }

-- Reputation discount on vendor and trainer prices: percent of the price paid by reaction
-- (4 Neutral … 8 Exalted). Checked in Forever: Friendly nothing, Honored 10 %. Data/RecipeSources.lua
-- brings the values Tools/build_sources.py derived from prices players paid (ns.db.discountSeen).
-- Vendors round up to whole copper, trainers down.
local discounts = { [4] = 100, [5] = 100, [6] = 90, [7] = 90, [8] = 90 }
local MIN_OBSERVED_PRICE = 100 -- copper; below that the rounding hides the discount

local packedSources, packedNPCs = {}, {}
local trainerFactions = {} -- [skill line] = { faction IDs whose trainers teach the profession }
local npcFactions = {}     -- [npc] = faction of trainers and reagent vendors
local sources, npcs = {}, {} -- unpacked on demand
local names = { n = {}, o = {}, q = {} } -- [ID] = name of NPCs, objects, quests

function ns.RegisterRecipeSources(list)
    for spellID, packed in pairs(list) do
        packedSources[spellID] = packed
    end
end

function ns.RegisterSourceNPCs(list)
    for npcID, packed in pairs(list) do
        packedNPCs[npcID] = packed
    end
end

function ns.RegisterTrainerFactions(list)
    for skillLine, packed in pairs(list) do
        local factions = {}
        for id in packed:gmatch("%d+") do
            factions[#factions + 1] = tonumber(id)
        end
        trainerFactions[skillLine] = factions
    end
end

function ns.RegisterNPCFactions(list)
    for npcID, factionID in pairs(list) do
        npcFactions[npcID] = factionID
    end
end

function ns.RegisterDiscounts(list)
    for reaction, percent in pairs(list) do
        discounts[reaction] = percent
    end
end

-- English first (Data/Names/enUS.lua), then the client's language on top
function ns.RegisterSourceNames(list)
    for kind, entries in pairs(list) do
        local target = names[kind]
        if target then
            for id, name in pairs(entries) do
                target[id] = name
            end
        end
    end
end

-- ----------------------------------------------------------------------------
-- Unpacking
-- ----------------------------------------------------------------------------
-- "field|field|…", the first character names the field (see Data/RecipeSources.lua)
-- "n40:2.5" -> { kind = "n", id = 40, chance = "2.5" }; "w5-25" -> world drop; "=Name" -> English text
local function UnpackDrop(token)
    local kind, rest = token:sub(1, 1), token:sub(2)
    if kind == "w" then
        return { kind = "w", text = (rest:gsub("-", "–")) }
    end
    local value, chance = rest:match("^(.-):([%d.]+)$")
    value = value or rest
    if kind == "=" then
        return { kind = "=", text = value, chance = chance }
    end
    return { kind = kind, id = tonumber(value), chance = chance }
end

local function Unpack(packed)
    local source = { kinds = {} }
    for field in packed:gmatch("[^|]+") do
        local kind, value = field:sub(1, 1), field:sub(2)
        if kind == "a" then
            source.auto = true
        elseif kind == "t" then
            local cost, alliance, horde, seen = value:match("^(%d+):(%d+):(%d+):(%d)")
            source.trainer = {
                cost = tonumber(cost) or 0, A = tonumber(alliance) or 0, H = tonumber(horde) or 0, seen = seen == "1",
            }
            source.kinds.TRAINER = true
        elseif kind == "i" then
            source.item = tonumber(value)
        elseif kind == "v" then
            local vendors = {}
            for npcID, price, limited in value:gmatch("(%d+):(%d+):(%d)") do
                vendors[#vendors + 1] = { npc = tonumber(npcID), price = tonumber(price), limited = limited == "1" }
            end
            source.vendors = vendors
            source.kinds.VENDOR = true
        elseif kind == "r" then
            source.faction = tonumber(value)
        elseif kind == "f" then
            source.favor = tonumber(value)
        elseif kind == "q" then
            local quests = {}
            for token in value:gmatch("[^,]+") do
                if token:sub(1, 1) == "=" then
                    quests[#quests + 1] = { text = token:sub(2) }
                else
                    quests[#quests + 1] = { id = tonumber(token) }
                end
            end
            source.quests = quests
            source.kinds.QUEST = true
        elseif kind == "d" then
            local drops = {}
            for token in value:gmatch("[^,]+") do
                drops[#drops + 1] = UnpackDrop(token)
            end
            source.drops = drops
            source.kinds.DROP = true
        elseif kind == "n" then
            source.dropCount = tonumber(value)
        elseif kind == "W" then
            -- Many drop sources, none named: the item's page on ForeverDB lists them
            source.worldDrop = true
            source.kinds.DROP = true
        elseif kind == "x" then
            source.uncertain = true
        end
    end
    if not next(source.kinds) then
        source.kinds.OTHER = true -- learned automatically, or only the recipe item is known
    end
    return source
end

-- Source of a recipe (or nil if nothing is known about it)
function ns.GetRecipeSource(spellID)
    local source = sources[spellID]
    if source == nil then
        local packed = packedSources[spellID]
        source = packed and Unpack(packed) or false
        sources[spellID] = source
    end
    return source or nil
end

-- Does the recipe have a source of this kind ("TRAINER", "VENDOR", "DROP", "QUEST", "OTHER")?
function ns.HasSourceKind(spellID, kind)
    local source = ns.GetRecipeSource(spellID)
    if not source then
        return kind == "OTHER"
    end
    return source.kinds[kind] == true
end

-- ----------------------------------------------------------------------------
-- Names: zones, factions and currencies from the client, the rest from Data/Names
-- ----------------------------------------------------------------------------
local playerSide
local function PlayerSide()
    if not playerSide then
        local faction = UnitFactionGroup and UnitFactionGroup("player")
        playerSide = (faction == "Horde" and "H") or (faction == "Alliance" and "A") or nil
    end
    return playerSide
end

local function SideName(side)
    if side == "H" then return FACTION_HORDE or "Horde" end
    return FACTION_ALLIANCE or "Alliance"
end

local function IsText(value)
    return type(value) == "string" and value ~= "" and not (issecretvalue and issecretvalue(value))
end

local zoneNames = {}
local function ZoneName(uiMapID)
    if not uiMapID or uiMapID == 0 then return nil end
    local name = zoneNames[uiMapID]
    if name == nil then
        name = false
        if C_Map and C_Map.GetMapInfo then
            local ok, info = pcall(C_Map.GetMapInfo, uiMapID)
            if ok and info and IsText(info.name) then
                name = info.name
            end
        end
        zoneNames[uiMapID] = name
    end
    return name or nil
end

local function FactionName(factionID)
    if C_Reputation and C_Reputation.GetFactionDataByID then
        local ok, data = pcall(C_Reputation.GetFactionDataByID, factionID)
        if ok and data and IsText(data.name) then return data.name end
    end
    if GetFactionInfoByID then
        local ok, name = pcall(GetFactionInfoByID, factionID)
        if ok and IsText(name) then return name end
    end
end

-- The character's reaction to a faction (1 Hated … 8 Exalted), or nil
local function Reaction(factionID)
    if not factionID then return nil end
    local reaction
    if C_Reputation and C_Reputation.GetFactionDataByID then
        local ok, data = pcall(C_Reputation.GetFactionDataByID, factionID)
        if ok and data then reaction = data.reaction end
    end
    if not reaction and GetFactionInfoByID then
        local ok, _, _, standingID = pcall(GetFactionInfoByID, factionID)
        if ok then reaction = standingID end
    end
    if type(reaction) ~= "number" or (issecretvalue and issecretvalue(reaction)) then return nil end
    return reaction
end

-- Percent of the price the character pays at this faction's vendors and trainers (100: no discount)
local function DiscountPercent(factionID)
    local reaction = Reaction(factionID)
    return reaction and discounts[reaction] or 100
end
ns.GetDiscountPercent = DiscountPercent

local function FavorName()
    if C_CurrencyInfo and C_CurrencyInfo.GetCurrencyInfo then
        local ok, info = pcall(C_CurrencyInfo.GetCurrencyInfo, MERCHANTS_FAVOR)
        if ok and info and IsText(info.name) then return info.name end
    end
    return L["SOURCE_FAVOR"]
end

local function ItemName(itemID)
    if ns.ItemName then
        return ns.ItemName(itemID) -- Tooltip.lua: also refreshes once the name has loaded
    end
    return C_Item.GetItemNameByID(itemID) or ("#" .. itemID)
end

function ns.FormatMoney(copper)
    if GetMoneyString then
        return GetMoneyString(copper, true)
    end
    local gold, silver = math.floor(copper / 10000), math.floor(copper / 100) % 100
    local parts = {}
    if gold > 0 then parts[#parts + 1] = gold .. "g" end
    if silver > 0 then parts[#parts + 1] = silver .. "s" end
    if copper % 100 > 0 or #parts == 0 then parts[#parts + 1] = (copper % 100) .. "c" end
    return table.concat(parts, " ")
end

local function GetNPC(npcID)
    local npc = npcs[npcID]
    if npc == nil then
        local packed = packedNPCs[npcID]
        npc = false
        if packed then
            local name, uiMapID, x, y, side, rest = packed:match("^([^|]*)|([^|]*)|([^|]*)|([^|]*)|([^|]*)|(.*)$")
            npc = {
                name = name, map = tonumber(uiMapID), x = tonumber(x) or 0, y = tonumber(y) or 0,
                side = side ~= "" and side or nil, faction = tonumber((rest or ""):match("^[^|]*|(%d+)")),
            }
        end
        npcs[npcID] = npc
    end
    return npc or nil
end

-- Vendor NPC: name, zone (or nil), x, y, side ("A", "H" or nil for both)
function ns.GetSourceNPC(npcID)
    local npc = GetNPC(npcID)
    if not npc then return nil end
    return names.n[npcID] or npc.name, ZoneName(npc.map), npc.x, npc.y, npc.side
end

-- ----------------------------------------------------------------------------
-- Text
-- ----------------------------------------------------------------------------
local function Colorize(color, text)
    return "|c" .. color .. text .. "|r"
end

local function Label(key)
    return Colorize(COLOR_LABEL, L[key] .. ":")
end

-- Vendors the character can buy from: never the other faction's.
-- Returns: list, and the other side ("A"/"H") if only its vendors sell the recipe
local function UsableVendors(vendors)
    local side = PlayerSide()
    local usable, otherSide = {}, nil
    for _, vendor in ipairs(vendors) do
        local npc = GetNPC(vendor.npc)
        if npc then
            if not side or not npc.side or npc.side == side then
                usable[#usable + 1] = vendor
            else
                otherSide = npc.side
            end
        end
    end
    return usable, #usable == 0 and otherSide or nil
end

local function VendorLine(vendor)
    local name, zone, x, y = ns.GetSourceNPC(vendor.npc)
    local text = Label("SOURCE_VENDOR") .. " " .. name
    if zone then
        text = text .. " – " .. zone
        if x > 0 or y > 0 then
            text = text .. string.format(" (%.1f, %.1f)", x, y)
        end
    end
    if vendor.price > 0 then
        local npc = GetNPC(vendor.npc)
        local percent = npc and DiscountPercent(npc.faction) or 100
        if percent < 100 then
            text = text .. " – " .. ns.FormatMoney(math.ceil(vendor.price * percent / 100)) .. " "
                .. Colorize(COLOR_NOTE, "(" .. string.format(L["SOURCE_DISCOUNT"], 100 - percent,
                    FactionName(npc.faction) or "?") .. ")")
        else
            text = text .. " – " .. ns.FormatMoney(vendor.price)
        end
    end
    if vendor.limited then
        text = text .. " " .. Colorize(COLOR_NOTE, "(" .. L["SOURCE_LIMITED"] .. ")")
    end
    return text
end

-- Best discount at trainers of this recipe's profession: percent paid and the factions that give it
local function DiscountTrainerFactions(spellID)
    local professionID
    if ns.GetRecipe then
        professionID = select(2, ns.GetRecipe(spellID))
    end
    local best, names = 100, {}
    for _, factionID in ipairs(professionID and trainerFactions[professionID] or {}) do
        local percent = DiscountPercent(factionID)
        if percent < best then
            best, names = percent, {}
        end
        if percent == best and percent < 100 then
            names[#names + 1] = FactionName(factionID) or ("#" .. factionID)
        end
    end
    return names, best
end

local function TrainerLine(trainer, spellID)
    local text = Colorize(COLOR_LABEL, L["SOURCE_TRAINER"] .. (trainer.cost > 0 and ":" or ""))
    if trainer.cost > 0 then
        local factions, percent = DiscountTrainerFactions(spellID)
        if #factions > 0 then
            -- Which trainer teaches the recipe isn't known: the full price stays in view
            text = text .. " " .. ns.FormatMoney(trainer.cost) .. " " .. Colorize(COLOR_NOTE, "("
                .. string.format(L["SOURCE_TRAINER_DISCOUNT"], ns.FormatMoney(math.floor(trainer.cost * percent / 100)),
                    table.concat(factions, ", ")) .. ")")
        else
            text = text .. " " .. ns.FormatMoney(trainer.cost)
        end
    end
    -- Taught only by the other faction's trainers
    local side = PlayerSide()
    local other = side == "A" and "H" or "A"
    if side and trainer[side] == 0 and trainer[other] > 0 then
        text = text .. " " .. Colorize(COLOR_NOTE, "(" .. SideName(other) .. ")")
    end
    return text
end

local function DropName(drop)
    local name
    if drop.kind == "w" then
        name = string.format(L["SOURCE_WORLD_DROP"], drop.text)
    elseif drop.kind == "=" then
        name = drop.text
    else
        name = names[drop.kind][drop.id] or ("#" .. drop.id)
    end
    return drop.chance and (name .. " " .. drop.chance .. "%") or name
end

local function QuestLine(quests)
    local titles = {}
    for index, quest in ipairs(quests) do
        titles[index] = quest.text or names.q[quest.id] or ("#" .. quest.id)
    end
    return Label("SOURCE_QUEST") .. " " .. table.concat(titles, ", ")
end

local function DropLine(source)
    local parts = {}
    for index, drop in ipairs(source.drops) do
        parts[index] = DropName(drop)
    end
    local text = Label("SOURCE_DROP") .. " " .. table.concat(parts, ", ")
    local more = (source.dropCount or 0) - #parts
    if more > 0 then
        text = text .. " " .. Colorize(COLOR_NOTE, "(+" .. more .. ")")
    end
    return text
end

-- Short form for lists, e.g. "Trainer" or "Vendor, Drop" (nil if nothing is known)
function ns.GetSourceSummary(spellID)
    local source = ns.GetRecipeSource(spellID)
    if not source then return nil end
    local parts = {}
    if source.trainer then parts[#parts + 1] = L["SOURCE_TRAINER"] end
    if source.vendors then parts[#parts + 1] = L["SOURCE_VENDOR"] end
    if source.quests then parts[#parts + 1] = L["SOURCE_QUEST"] end
    if source.drops or source.worldDrop then parts[#parts + 1] = L["SOURCE_DROP"] end
    if #parts == 0 then
        parts[1] = source.auto and L["SOURCE_AUTO"] or L["SOURCE_ITEM"]
    end
    return table.concat(parts, ", ") .. (source.uncertain and " ?" or "")
end

-- Detailed lines (colored), e.g. for a tooltip. maxVendors limits the vendor list.
-- Returns nil if nothing is known about the recipe.
function ns.GetSourceLines(spellID, maxVendors)
    local source = ns.GetRecipeSource(spellID)
    if not source then return nil end
    local lines = {}
    if source.auto then
        lines[#lines + 1] = Colorize(COLOR_LABEL, L["SOURCE_AUTO"])
    end
    if source.trainer then
        lines[#lines + 1] = TrainerLine(source.trainer, spellID)
    end
    if source.item then
        lines[#lines + 1] = Label("SOURCE_ITEM") .. " " .. ItemName(source.item)
    end
    if source.vendors then
        local vendors, otherSide = UsableVendors(source.vendors)
        local limit = maxVendors or #vendors
        for index = 1, math.min(#vendors, limit) do
            lines[#lines + 1] = VendorLine(vendors[index])
        end
        if #vendors > limit then
            lines[#lines + 1] = "   " .. Colorize(COLOR_NOTE, string.format(L["SOURCE_MORE_VENDORS"], #vendors - limit))
        elseif #vendors == 0 then
            -- Sold, but the vendor is unknown or belongs to the other faction (no place then)
            lines[#lines + 1] = Colorize(COLOR_LABEL, L["SOURCE_VENDOR"])
                .. (otherSide and (" " .. Colorize(COLOR_NOTE, "(" .. SideName(otherSide) .. ")")) or "")
        end
    end
    if source.faction then
        local name = FactionName(source.faction)
        lines[#lines + 1] = name and (Label("SOURCE_REPUTATION") .. " " .. name) or Colorize(COLOR_LABEL, L["SOURCE_REPUTATION"])
    end
    if source.favor then
        lines[#lines + 1] = Colorize(COLOR_LABEL, FavorName() .. ":") .. " " .. source.favor
    end
    if source.quests then
        lines[#lines + 1] = QuestLine(source.quests)
    end
    if source.drops then
        lines[#lines + 1] = DropLine(source)
    end
    if source.worldDrop then
        lines[#lines + 1] = Label("SOURCE_DROP") .. " " .. L["SOURCE_WORLD_DROP_MANY"]
    end
    if source.uncertain then
        lines[#lines + 1] = Colorize(COLOR_NOTE, L["SOURCE_UNCERTAIN"])
    end
    return lines
end

-- ----------------------------------------------------------------------------
-- Observed discounts: what the character paid compared to the base price in the data, by
-- reaction. Tools/build_sources.py derives the discount of each reaction from these.
-- ----------------------------------------------------------------------------
local vendorBase -- ["npc:item"] = price of a recipe item at this vendor

-- Base price of an item at a vendor: price (whole stack) and whether it is a unit price
function ns.GetVendorBasePrice(npcID, itemID)
    if not vendorBase then
        vendorBase = {}
        for _, packed in pairs(packedSources) do
            local item = packed:match("^i(%d+)") or packed:match("|i(%d+)")
            local list = packed:match("^v([^|]*)") or packed:match("|v([^|]*)")
            if item and list then
                for npc, price in list:gmatch("(%d+):(%d+):%d") do
                    vendorBase[npc .. ":" .. item] = tonumber(price)
                end
            end
        end
    end
    local price = vendorBase[npcID .. ":" .. itemID]
    if price and price > 0 then return price, false end
    local unit = ns.GetVendorPrice and ns.GetVendorPrice(itemID)
    if unit and unit > 0 then return unit, true end
end

function ns.GetNPCFaction(npcID)
    local npc = GetNPC(npcID)
    return npc and npc.faction or npcFactions[npcID]
end

-- kind "v" (vendor, id = item) or "t" (trainer, id = spell); base and paid in copper
function ns.ObserveDiscount(kind, npcID, id, base, paid)
    if not (ns.db and npcID and id and base and paid) or base < MIN_OBSERVED_PRICE or paid <= 0 then return end
    local reaction = Reaction(ns.GetNPCFaction(npcID))
    local ratio = paid / base
    if not reaction or ratio < 0.5 or ratio > 1.2 then return end
    ns.db.discountSeen = ns.db.discountSeen or {}
    ns.db.discountSeen[kind .. npcID .. ":" .. id] = string.format("%d:%.2f", reaction, ratio)
end

-- Page with all details on ForeverDB (where the source data comes from): the recipe item, which
-- lists every creature it drops from, or the recipe spell if there is no recipe item.
function ns.GetSourceLink(spellID)
    local source = ns.GetRecipeSource(spellID)
    if source and source.item then
        return "https://foreverdb.net/item/" .. source.item
    end
    return "https://foreverdb.net/spell/" .. spellID
end

-- ----------------------------------------------------------------------------
-- Map
-- ----------------------------------------------------------------------------
-- Vendor to walk to: one in the zone the character is in, otherwise the first one.
-- Returns: name, uiMapID, x, y (or nil if no vendor with a known place sells the recipe)
function ns.GetSourceWaypoint(spellID)
    local source = ns.GetRecipeSource(spellID)
    if not (source and source.vendors) then return nil end
    local current
    if C_Map and C_Map.GetBestMapForUnit then
        local ok, mapID = pcall(C_Map.GetBestMapForUnit, "player")
        current = ok and mapID or nil
    end
    local best
    for _, vendor in ipairs((UsableVendors(source.vendors))) do
        local npc = GetNPC(vendor.npc)
        if npc.map and npc.map > 0 and (npc.x > 0 or npc.y > 0) then
            if npc.map == current then
                best = vendor.npc
                break
            end
            best = best or vendor.npc
        end
    end
    if not best then return nil end
    local npc = GetNPC(best)
    return names.n[best] or npc.name, npc.map, npc.x, npc.y
end

-- Opens the world map on the vendor's zone and marks the vendor: the game's own map pin,
-- and TomTom's arrow if TomTom is installed. Returns true if there was a place to show.
function ns.ShowSourceOnMap(spellID)
    local name, mapID, x, y = ns.GetSourceWaypoint(spellID)
    if not name then return false end
    if C_Map and C_Map.SetUserWaypoint and UiMapPoint and UiMapPoint.CreateFromCoordinates
        and not (C_Map.CanSetUserWaypointOnMap and not C_Map.CanSetUserWaypointOnMap(mapID)) then
        pcall(function()
            C_Map.SetUserWaypoint(UiMapPoint.CreateFromCoordinates(mapID, x / 100, y / 100))
            if C_SuperTrack and C_SuperTrack.SetSuperTrackedUserWaypoint then
                C_SuperTrack.SetSuperTrackedUserWaypoint(true)
            end
        end)
    end
    if TomTom and TomTom.AddWaypoint then
        pcall(TomTom.AddWaypoint, TomTom, mapID, x / 100, y / 100, { title = name, from = "Profession Tooltip" })
    end
    if OpenWorldMap then
        pcall(OpenWorldMap, mapID)
    end
    return true
end
